function escape(value) { return String(value??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }
return $input.all().map((item,index)=>{
  const e=item.json, config=e.config || $('Validate Configuration').first().json.config;
  const lines=['PATCHGUARD — '+e.event,'Repository: '+config.owner+'/'+config.repository];
  if(e.package) lines.push('Package: '+e.package+' | installed '+e.installed_version+' → '+(e.fixed_version||'no fix'));
  if(e.advisory_id) lines.push(e.advisory_id+' '+e.cve_id+' | '+e.severity+' | KEV: '+(e.knownExploited===null?'UNKNOWN':e.knownExploited));
  if(e.scanStatus==='incomplete') lines.push('INCOMPLETE: do not interpret this as zero vulnerabilities.');
  for(const reason of e.reasons || []) lines.push('• '+String(reason).slice(0,300));
  if(e.url) lines.push(e.url);
  if(e.runUrl) lines.push(e.runUrl);
  const message=escape(lines.join('\n').slice(0,3500));
  return {json:{...e,config,telegramText:message,notificationWanted:config.telegramEnabled===true && /^-?\d{1,20}$/.test(String(config.telegramChatId || ''))},pairedItem:{item:index}};
});
